        tree.assign(2 * n, (1 << 31) - 1);
        lazy.assign(2 * n, false);
        lazyVal.assign(2 * n, 0);
    }

    void apply(int idx, int val) {
        tree[idx] = val;
        lazy[idx] = true;
        lazyVal[idx] = val;
    }

    void push(int idx) {
        if (lazy[idx]) {
            apply(idx * 2, lazyVal[idx]);
            apply(idx * 2 + 1, lazyVal[idx]);
            lazy[idx] = false;
        }
    }

    void update(int l, int r, int x, int idx, int left, int right) {
        if (l <= left && right <= r) {
            apply(idx, x);
            return;
        }
        push(idx);
        int mid = (left + right) / 2;
        if (l < mid) update(l, r, x, idx * 2, left, mid);
        if (r > mid) update(l, r, x, idx * 2 + 1, mid, right);
    }

    void update(int l, int r, int x) {
        update(l, r, x, 1, 0, n);
    }

