        push(idx);
        int mid = (left + right) / 2;
        if (pos < mid)
            return query(pos, idx * 2, left, mid);
        else
            return query(pos, idx * 2 + 1, mid, right);
    }

    int query(int pos) {
        return query(pos, 1, 0, n);
    }
