typedef struct {
    int l, r;
    int val;
    int lazy;
    int has_lazy;
} Node;

static Node *seg;
static int N;

void build(int idx, int l, int r, int init_val) {
    seg[idx].l = l;
    seg[idx].r = r;
    seg[idx].val = init_val;
    seg[idx].lazy = 0;
    seg[idx].has_lazy = 0;
    if (l == r) return;
    int m = (l + r) >> 1;
    build(idx << 1, l, m, init_val);
    build(idx << 1 | 1, m + 1, r, init_val);
}

void push(int idx) {
    if (!seg[idx].has_lazy || seg[idx].l == seg[idx].r) return;
    int v = seg[idx].lazy;
    int lc = idx << 1, rc = idx << 1 | 1;

    seg[lc].val = v;
    seg[lc].lazy = v;
    seg[lc].has_lazy = 1;

    seg[rc].val = v;
    seg[rc].lazy = v;
    seg[rc].has_lazy = 1;

    seg[idx].has_lazy = 0;
}

void update(int idx, int ql, int qr, int x) {
    int l = seg[idx].l, r = seg[idx].r;
    if (qr < l || r < ql) return;
    if (ql <= l && r <= qr) {
        seg[idx].val = x;
        seg[idx].lazy = x;
        seg[idx].has_lazy = 1;
        return;
    }
    push(idx);
    update(idx << 1, ql, qr, x);
    update(idx << 1 | 1, ql, qr, x);
}

int find_value(int idx, int pos) {
    int l = seg[idx].l, r = seg[idx].r;
    if (l == r) return seg[idx].val;
    push(idx);
    int m = (l + r) >> 1;
    if (pos <= m) return find_value(idx << 1, pos);
    return find_value(idx << 1 | 1, pos);
}

int main(void) {
