public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class SegmentTree {
        int n;
        int[] lazy;
        boolean[] has;

        SegmentTree(int size) {
            n = 1;
            while (n < size) n <<= 1;
            lazy = new int[n << 1];
            has = new boolean[n << 1];
        }

        void update(int l, int r, int x) {
            update(l, r, x, 1, 0, n);
        }

        private void update(int l, int r, int x, int node, int nl, int nr) {
            if (r <= nl || nr <= l) return;
            if (l <= nl && nr <= r) {
                lazy[node] = x;
                has[node] = true;
                return;
            }
            push(node);
            int mid = (nl + nr) >>> 1;
            update(l, r, x, node << 1, nl, mid);
            update(l, r, x, node << 1 | 1, mid, nr);
        }

        int get(int idx) {
            return get(idx, 1, 0, n, Integer.MAX_VALUE);
        }

        private int get(int idx, int node, int nl, int nr, int inherited) {
            if (has[node]) inherited = lazy[node];
            if (nr - nl == 1) return inherited;
            int mid = (nl + nr) >>> 1;
            if (idx < mid) return get(idx, node << 1, nl, mid, inherited);
            else return get(idx, node << 1 | 1, mid, nr, inherited);
        }

        private void push(int node) {
            if (has[node]) {
                int left = node << 1;
                int right = left | 1;
                lazy[left] = lazy[node];
                lazy[right] = lazy[node];
                has[left] = true;
                has[right] = true;
                has[node] = false;
            }
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        StringBuilder out = new StringBuilder();

        int n = fs.nextInt();
        int q = fs.nextInt();

        SegmentTree st = new SegmentTree(n);
        final int INIT = Integer.MAX_VALUE;

        for (int i = 0; i < q; i++) {
            int com = fs.nextInt();
            if (com == 0) {
                int s = fs.nextInt();
                int t = fs.nextInt();
                int x = fs.nextInt();
                st.update(s, t + 1, x);
            } else {
                int idx = fs.nextInt();
                int ans = st.get(idx);
                if (ans == Integer.MAX_VALUE) ans = INIT;
                out.append(ans).append('\n');
            }
        }

        System.out.print(out.toString());
    }
}

