                a = m

    out = []
    for _ in range(q):
        query = list(map(int, input().split()))
        if query[0] == 0:
            _, s, t, x = query
            update(s, t + 1, x, 1, 0, size)
        else:
            _, i = query
            out.append(str(find(i)))

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()
